package ch.varani.boxone.detour;

import ch.varani.boxone.core.GeoPoint;
import ch.varani.boxone.core.Route;
import ch.varani.boxone.routing.RoadKind;

import java.util.List;
import java.util.Objects;
import java.util.Set;

/**
 * A detour generated by the {@link DetourGenerator}: the route through its waypoints, the fastest route it is
 * compared with, its budget, the kinds of road it never drives and the seed it was drawn from (development plan,
 * phase 3).
 *
 * <p>The same seed, with the same start, finish, budget, kinds of road forbidden and map, gives the same detour: the
 * seed is shown to the user so that a detour can be generated again.</p>
 *
 * <p>Its routes and waypoints are personal data (AGENTS.md §5): a detour is never logged.</p>
 *
 * <p>Immutable, safe for concurrent use.</p>
 *
 * @param route the route through the waypoints, from the start to the finish.
 * @param fastest the fastest route from the start to the finish.
 * @param waypoints the waypoints drawn, in the order the route passes them; unmodifiable.
 * @param budget the budget of the detour: the route is longer than the fastest route by its duration at most
 *               ({@link Budget#of(java.time.Duration)} of the duration of the fastest route).
 * @param avoided the kinds of road the fastest route and the detour never drive (issue #11 of GitLab); unmodifiable.
 * @param seed the seed of the random draws.
 */
public record Detour(Route route, Route fastest, List<GeoPoint> waypoints, Budget budget, Set<RoadKind> avoided,
                     long seed) {

  // *******************************************************************************************************************
  // Construction & Initialization
  // *******************************************************************************************************************

  /**
   * Creates a detour.
   *
   * @param route the route through the waypoints.
   * @param fastest the fastest route from the start to the finish.
   * @param waypoints the waypoints, in the order the route passes them, none {@code null}; copied.
   * @param budget the budget of the detour.
   * @param avoided the kinds of road forbidden, none {@code null}; copied.
   * @param seed the seed of the random draws.
   *
   * @throws NullPointerException if a route, the list of the waypoints, one of them, the budget, the set of the kinds
   *                              forbidden or one of them is {@code null}.
   */
  public Detour {
    Objects.requireNonNull(route);
    Objects.requireNonNull(fastest);
    waypoints = List.copyOf(waypoints);
    Objects.requireNonNull(budget);
    avoided = Set.copyOf(avoided);
  }

}
